//! The app-owned shadcn Neutral theme for gpuicn.
//!
//! Source: shadcn/ui 4.19.0 at
//! `1773ecfeeb4a04366978d353e69b5c7ded78dcb2`, Nova style.

use gpui::{App, Global, Pixels, Rgba, SharedString, px};

/// The active color mode.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ThemeMode {
    /// The Neutral light palette.
    Light,
    /// The Neutral dark palette.
    Dark,
}

/// Semantic colors consumed by installed components.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiColors {
    /// App background.
    pub background: Rgba,
    /// Default foreground.
    pub foreground: Rgba,
    /// Card background.
    pub card: Rgba,
    /// Card foreground.
    pub card_foreground: Rgba,
    /// Popover background.
    pub popover: Rgba,
    /// Popover foreground.
    pub popover_foreground: Rgba,
    /// Primary control background.
    pub primary: Rgba,
    /// Primary control foreground.
    pub primary_foreground: Rgba,
    /// Secondary control background.
    pub secondary: Rgba,
    /// Secondary control foreground.
    pub secondary_foreground: Rgba,
    /// Muted background.
    pub muted: Rgba,
    /// Muted foreground.
    pub muted_foreground: Rgba,
    /// Accent background.
    pub accent: Rgba,
    /// Accent foreground.
    pub accent_foreground: Rgba,
    /// Destructive action color.
    pub destructive: Rgba,
    /// Default border.
    pub border: Rgba,
    /// Input border.
    pub input: Rgba,
    /// Focus ring.
    pub ring: Rgba,
    /// First chart color.
    pub chart_1: Rgba,
    /// Second chart color.
    pub chart_2: Rgba,
    /// Third chart color.
    pub chart_3: Rgba,
    /// Fourth chart color.
    pub chart_4: Rgba,
    /// Fifth chart color.
    pub chart_5: Rgba,
    /// Sidebar background.
    pub sidebar: Rgba,
    /// Sidebar foreground.
    pub sidebar_foreground: Rgba,
    /// Sidebar primary background.
    pub sidebar_primary: Rgba,
    /// Sidebar primary foreground.
    pub sidebar_primary_foreground: Rgba,
    /// Sidebar accent background.
    pub sidebar_accent: Rgba,
    /// Sidebar accent foreground.
    pub sidebar_accent_foreground: Rgba,
    /// Sidebar border.
    pub sidebar_border: Rgba,
    /// Sidebar focus ring.
    pub sidebar_ring: Rgba,
}

/// Theme font family names. Applications own font loading.
#[derive(Clone, Debug, PartialEq)]
pub struct UiFonts {
    /// Default body family.
    pub body: SharedString,
    /// Default heading family.
    pub heading: SharedString,
    /// Default monospace family.
    pub mono: SharedString,
}

/// Base corner radius from the pinned shadcn theme.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiRadius {
    /// Ten pixels (`0.625rem` at the shadcn 16px root size).
    pub base: Pixels,
}

/// Base spacing unit from the pinned Nova style.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiSpacing {
    /// Four pixels.
    pub unit: Pixels,
}

/// The application-owned theme stored in GPUI global state.
#[derive(Clone, Debug, PartialEq)]
pub struct UiTheme {
    /// Active color mode.
    pub mode: ThemeMode,
    /// Active semantic colors.
    pub colors: UiColors,
    /// Font family names.
    pub fonts: UiFonts,
    /// Base corner radius.
    pub radius: UiRadius,
    /// Base spacing unit.
    pub spacing: UiSpacing,
}

impl Global for UiTheme {}

impl Default for UiTheme {
    fn default() -> Self {
        Self::neutral_light()
    }
}

impl UiTheme {
    /// Creates the pinned Neutral light theme.
    pub fn neutral_light() -> Self {
        Self::new(ThemeMode::Light, neutral_light_colors())
    }

    /// Creates the pinned Neutral dark theme.
    pub fn neutral_dark() -> Self {
        Self::new(ThemeMode::Dark, neutral_dark_colors())
    }

    /// Installs a theme into the application.
    pub fn set(cx: &mut App, theme: Self) {
        cx.set_global(theme);
    }

    /// Reads the installed theme.
    ///
    /// Panics when the application has not installed a theme.
    pub fn read(cx: &App) -> &Self {
        cx.global::<Self>()
    }

    /// Replaces the installed theme with the pinned palette for `mode`.
    pub fn switch(cx: &mut App, mode: ThemeMode) {
        Self::set(
            cx,
            match mode {
                ThemeMode::Light => Self::neutral_light(),
                ThemeMode::Dark => Self::neutral_dark(),
            },
        );
    }

    fn new(mode: ThemeMode, colors: UiColors) -> Self {
        Self {
            mode,
            colors,
            fonts: UiFonts {
                body: "Geist".into(),
                heading: "Geist".into(),
                mono: "Geist Mono".into(),
            },
            radius: UiRadius { base: px(10.) },
            spacing: UiSpacing { unit: px(4.) },
        }
    }
}

fn neutral_light_colors() -> UiColors {
    UiColors {
        background: neutral(1.0),
        foreground: neutral(0.145),
        card: neutral(1.0),
        card_foreground: neutral(0.145),
        popover: neutral(1.0),
        popover_foreground: neutral(0.145),
        primary: neutral(0.205),
        primary_foreground: neutral(0.985),
        secondary: neutral(0.97),
        secondary_foreground: neutral(0.205),
        muted: neutral(0.97),
        muted_foreground: neutral(0.556),
        accent: neutral(0.97),
        accent_foreground: neutral(0.205),
        destructive: srgb(0xdc, 0x26, 0x26),
        border: neutral(0.922),
        input: neutral(0.922),
        ring: neutral(0.708),
        chart_1: neutral(0.87),
        chart_2: neutral(0.556),
        chart_3: neutral(0.439),
        chart_4: neutral(0.371),
        chart_5: neutral(0.269),
        sidebar: neutral(0.985),
        sidebar_foreground: neutral(0.145),
        sidebar_primary: neutral(0.205),
        sidebar_primary_foreground: neutral(0.985),
        sidebar_accent: neutral(0.97),
        sidebar_accent_foreground: neutral(0.205),
        sidebar_border: neutral(0.922),
        sidebar_ring: neutral(0.708),
    }
}

fn neutral_dark_colors() -> UiColors {
    UiColors {
        background: neutral(0.145),
        foreground: neutral(0.985),
        card: neutral(0.205),
        card_foreground: neutral(0.985),
        popover: neutral(0.205),
        popover_foreground: neutral(0.985),
        primary: neutral(0.922),
        primary_foreground: neutral(0.205),
        secondary: neutral(0.269),
        secondary_foreground: neutral(0.985),
        muted: neutral(0.269),
        muted_foreground: neutral(0.708),
        accent: neutral(0.269),
        accent_foreground: neutral(0.985),
        destructive: srgb(0xff, 0x64, 0x67),
        border: neutral_alpha(1.0, 0.10),
        input: neutral_alpha(1.0, 0.15),
        ring: neutral(0.556),
        chart_1: neutral(0.87),
        chart_2: neutral(0.556),
        chart_3: neutral(0.439),
        chart_4: neutral(0.371),
        chart_5: neutral(0.269),
        sidebar: neutral(0.205),
        sidebar_foreground: neutral(0.985),
        sidebar_primary: srgb(0x14, 0x47, 0xe6),
        sidebar_primary_foreground: neutral(0.985),
        sidebar_accent: neutral(0.269),
        sidebar_accent_foreground: neutral(0.985),
        sidebar_border: neutral_alpha(1.0, 0.10),
        sidebar_ring: neutral(0.556),
    }
}

pub(super) fn neutral(l: f64) -> Rgba {
    neutral_alpha(l, 1.0)
}

fn neutral_alpha(l: f64, alpha: f64) -> Rgba {
    let channel = srgb_channel(l * l * l) as f32;

    Rgba {
        r: channel,
        g: channel,
        b: channel,
        a: alpha.clamp(0.0, 1.0) as f32,
    }
}

const fn srgb(red: u8, green: u8, blue: u8) -> Rgba {
    Rgba {
        r: red as f32 / 255.0,
        g: green as f32 / 255.0,
        b: blue as f32 / 255.0,
        a: 1.0,
    }
}

fn srgb_channel(channel: f64) -> f64 {
    if channel >= 0.003_130_8 {
        (1.055 * channel.powf(1.0 / 2.4) - 0.055).clamp(0.0, 1.0)
    } else {
        (12.92 * channel).clamp(0.0, 1.0)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn converts_pinned_neutral_tokens() {
        assert_eq!(
            neutral(1.0),
            Rgba {
                r: 1.0,
                g: 1.0,
                b: 1.0,
                a: 1.0,
            }
        );
        assert_eq!(
            neutral(0.0),
            Rgba {
                r: 0.0,
                g: 0.0,
                b: 0.0,
                a: 1.0,
            }
        );

        assert_eq!(neutral_light_colors().destructive, srgb(0xdc, 0x26, 0x26));
        assert_eq!(neutral_dark_colors().destructive, srgb(0xff, 0x64, 0x67));
        assert_eq!(
            neutral_dark_colors().sidebar_primary,
            srgb(0x14, 0x47, 0xe6)
        );
    }

    #[test]
    fn preserves_pinned_alpha_tokens() {
        let dark = neutral_dark_colors();
        assert_eq!(dark.border.a, 0.10);
        assert_eq!(dark.input.a, 0.15);
        assert_eq!(dark.sidebar_border.a, 0.10);
    }
}

//! The shadcn Nova Combobox visual port.
//!
//! Visual source: shadcn/ui 4.19.0 `combobox.tsx` and `style-nova.css` at
//! `1773ecfeeb4a04366978d353e69b5c7ded78dcb2`. Interaction comes from the
//! pinned Base GPUI combobox primitives.

pub use base_gpui::combobox::{
    ComboboxAlign, ComboboxArrow, ComboboxBackdrop, ComboboxChip, ComboboxChipRemove,
    ComboboxChips, ComboboxClear, ComboboxCollection, ComboboxEmpty, ComboboxGroup,
    ComboboxGroupLabel, ComboboxIcon, ComboboxInput, ComboboxInputGroup, ComboboxItem,
    ComboboxItemIndicator, ComboboxLabel, ComboboxList, ComboboxPopup, ComboboxPortal,
    ComboboxPositioner, ComboboxRoot, ComboboxSelectionMode, ComboboxSeparator, ComboboxSide,
    ComboboxStatus, ComboboxTrigger, ComboboxValue,
};
use gpui::{
    App, BoxShadow, Div, ElementId, FontWeight, InteractiveElement as _, ParentElement as _,
    Styled, prelude::FluentBuilder as _, px,
};
use gpui_icons::{LucideIcon, lucide};

use super::theme::UiTheme;

/// Creates a combobox root with a caller-owned stable ID.
pub fn combobox_root<T: Clone + Eq + 'static>(id: impl Into<ElementId>) -> ComboboxRoot<T> {
    ComboboxRoot::new().id(id)
}

/// Creates the styled editable combobox input.
pub fn combobox_input<T: Clone + Eq + 'static>(
    id: impl Into<ElementId>,
    cx: &App,
) -> ComboboxInput<T> {
    let theme = UiTheme::read(cx).clone();
    ComboboxInput::new()
        .id(id)
        .style_with_state(move |state, base| {
            let ring = theme.colors.ring.alpha(0.50);
            base.h(px(32.))
                .rounded(theme.radius.base)
                .border_1()
                .border_color(theme.colors.input)
                .bg(theme.colors.background)
                .when(state.root.focused, |base| {
                    base.border_color(theme.colors.ring).shadow(vec![
                        BoxShadow::new(px(0.), px(0.), ring.into()).spread_radius(px(3.)),
                    ])
                })
                .when(state.root.disabled, |base| base.opacity(0.5))
        })
        .input_style_with_state(move |_state, base| {
            base.w_full()
                .h_full()
                .px(px(10.))
                .font_family(theme.fonts.body.clone())
                .text_size(px(14.))
                .text_color(theme.colors.foreground)
        })
}

/// Creates the borderless input used inside [`combobox_input_group`].
pub fn combobox_group_input<T: Clone + Eq + 'static>(
    id: impl Into<ElementId>,
    cx: &App,
) -> ComboboxInput<T> {
    let theme = UiTheme::read(cx).clone();
    ComboboxInput::new()
        .id(id)
        .style_with_state(move |_state, base| base.h(px(30.)).flex_1())
        .input_style_with_state(move |_state, base| {
            base.w_full()
                .h_full()
                .font_family(theme.fonts.body.clone())
                .text_size(px(14.))
                .text_color(theme.colors.foreground)
        })
}

/// Creates the styled input group used by chips and custom combobox layouts.
pub fn combobox_input_group<T: Clone + Eq + 'static>(cx: &App) -> ComboboxInputGroup<T> {
    let theme = UiTheme::read(cx).clone();
    ComboboxInputGroup::new().style_with_state(move |state, base| {
        base.flex()
            .items_center()
            .min_h(px(32.))
            .gap(px(4.))
            .rounded(theme.radius.base)
            .border_1()
            .border_color(theme.colors.input)
            .px(px(10.))
            .py(px(4.))
            .bg(if theme.mode == super::theme::ThemeMode::Dark {
                theme.colors.input.alpha(0.30)
            } else {
                theme.colors.background
            })
            .when(state.root.focused, |base| {
                base.border_color(theme.colors.ring).shadow(vec![
                    BoxShadow::new(px(0.), px(0.), theme.colors.ring.alpha(0.50).into())
                        .spread_radius(px(3.)),
                ])
            })
            .when(state.root.disabled, |base| base.opacity(0.5))
    })
}

/// Creates the styled combobox trigger with Nova's chevron.
pub fn combobox_trigger<T: Clone + Eq + 'static>(
    id: impl Into<ElementId>,
    cx: &App,
) -> ComboboxTrigger<T> {
    let theme = UiTheme::read(cx).clone();
    let icon_color = theme.colors.muted_foreground;
    ComboboxTrigger::new()
        .id(id)
        .style_with_state(move |state, base| {
            base.flex()
                .size(px(24.))
                .items_center()
                .justify_center()
                .rounded(px(6.))
                .text_color(theme.colors.muted_foreground)
                .when(state.root.open, |base| base.bg(theme.colors.muted))
                .when(!state.root.disabled, |base| {
                    base.hover(move |style| style.bg(theme.colors.muted))
                })
        })
        .child(
            lucide(LucideIcon::ChevronDown)
                .size(px(16.))
                .text_color(icon_color),
        )
}

/// Creates the styled clear control for a combobox.
pub fn combobox_clear<T: Clone + Eq + 'static>(
    id: impl Into<ElementId>,
    cx: &App,
) -> ComboboxClear<T> {
    let theme = UiTheme::read(cx).clone();
    ComboboxClear::new()
        .id(id)
        .style_with_state(move |state, base| {
            base.flex()
                .size(px(24.))
                .items_center()
                .justify_center()
                .rounded(px(6.))
                .text_color(theme.colors.muted_foreground)
                .when(!state.disabled, |base| {
                    base.hover(move |style| style.bg(theme.colors.muted))
                })
                .when(state.disabled, |base| base.opacity(0.5))
        })
        .child(
            lucide(LucideIcon::X)
                .size(px(14.))
                .text_color(theme.colors.muted_foreground),
        )
}

/// Creates the in-canvas combobox portal.
pub fn combobox_portal<T: Clone + Eq + 'static>() -> ComboboxPortal<T> {
    ComboboxPortal::new()
}

/// Creates a combobox positioner with the pinned 6px content offset.
pub fn combobox_positioner<T: Clone + Eq + 'static>() -> ComboboxPositioner<T> {
    ComboboxPositioner::new().side_offset(px(6.))
}

/// Creates the styled combobox popup.
pub fn combobox_popup<T: Clone + Eq + 'static>(cx: &App) -> ComboboxPopup<T> {
    let theme = UiTheme::read(cx).clone();
    ComboboxPopup::new().style_with_state(move |_state, base| popup_style(base, &theme))
}

/// Creates the styled combobox list.
pub fn combobox_list<T: Clone + Eq + 'static>() -> ComboboxList<T> {
    ComboboxList::new()
        .style_with_state(move |_state, base| base.max_h(px(252.)).overflow_hidden().p(px(4.)))
}

/// Creates a styled combobox item.
pub fn combobox_item<T: Clone + Eq + 'static>(
    id: impl Into<ElementId>,
    cx: &App,
) -> ComboboxItem<T> {
    let theme = UiTheme::read(cx).clone();
    ComboboxItem::new()
        .id(id)
        .style_with_state(move |state, base| {
            base.relative()
                .flex()
                .items_center()
                .gap(px(8.))
                .rounded(px(6.))
                .py(px(4.))
                .pr(px(32.))
                .pl(px(6.))
                .font_family(theme.fonts.body.clone())
                .text_size(px(14.))
                .text_color(theme.colors.popover_foreground)
                .when(state.highlighted, |base| {
                    base.bg(theme.colors.accent)
                        .text_color(theme.colors.accent_foreground)
                })
                .when(state.disabled, |base| base.opacity(0.5))
        })
        .child(combobox_item_indicator(cx))
}

/// Creates the selected-item check indicator.
pub fn combobox_item_indicator<T: Clone + Eq + 'static>(cx: &App) -> ComboboxItemIndicator<T> {
    let theme = UiTheme::read(cx).clone();
    ComboboxItemIndicator::new()
        .style_with_state(move |_state, base| {
            base.absolute()
                .right(px(8.))
                .flex()
                .size(px(16.))
                .items_center()
                .justify_center()
        })
        .child(
            lucide(LucideIcon::Check)
                .size(px(16.))
                .text_color(theme.colors.foreground),
        )
}

/// Creates a styled combobox group.
pub fn combobox_group<T: Clone + Eq + 'static>() -> ComboboxGroup<T> {
    ComboboxGroup::new().style_with_state(move |_state, base| base.p(px(4.)))
}

/// Creates a styled combobox group label.
pub fn combobox_group_label<T: Clone + Eq + 'static>(cx: &App) -> ComboboxGroupLabel<T> {
    let theme = UiTheme::read(cx).clone();
    ComboboxGroupLabel::new().style_with_state(move |_state, base| {
        base.px(px(8.))
            .py(px(6.))
            .font_family(theme.fonts.body.clone())
            .text_size(px(12.))
            .text_color(theme.colors.muted_foreground)
    })
}

/// Creates the styled empty state container.
pub fn combobox_empty<T: Clone + Eq + 'static>(cx: &App) -> ComboboxEmpty<T> {
    let theme = UiTheme::read(cx).clone();
    ComboboxEmpty::new().style_with_state(move |_state, base| {
        base.flex()
            .w_full()
            .justify_center()
            .py(px(8.))
            .font_family(theme.fonts.body.clone())
            .text_size(px(14.))
            .text_color(theme.colors.muted_foreground)
    })
}

/// Creates a styled combobox separator.
pub fn combobox_separator(cx: &App) -> ComboboxSeparator {
    let theme = UiTheme::read(cx).clone();
    ComboboxSeparator::new().style_with_state(move |_state, base| {
        base.h(px(1.))
            .mx(px(-4.))
            .my(px(4.))
            .bg(theme.colors.border)
    })
}

/// Creates the styled container for selected chips.
pub fn combobox_chips<T: Clone + Eq + 'static>(cx: &App) -> ComboboxChips<T> {
    let theme = UiTheme::read(cx).clone();
    ComboboxChips::new().style_with_state(move |_state, base| {
        base.flex()
            .flex_wrap()
            .items_center()
            .gap(px(4.))
            .font_family(theme.fonts.body.clone())
    })
}

/// Creates one styled selected-value chip.
pub fn combobox_chip<T: Clone + Eq + 'static>(cx: &App) -> ComboboxChip<T> {
    let theme = UiTheme::read(cx).clone();
    ComboboxChip::new().style_with_state(move |state, base| {
        base.flex()
            .items_center()
            .gap(px(4.))
            .h(px(21.))
            .rounded(px(4.))
            .px(px(6.))
            .bg(theme.colors.muted)
            .font_family(theme.fonts.body.clone())
            .font_weight(FontWeight::MEDIUM)
            .text_size(px(12.))
            .text_color(theme.colors.foreground)
            .when(state.highlighted, |base| base.bg(theme.colors.accent))
            .when(state.disabled, |base| base.opacity(0.5))
    })
}

/// Creates the styled remove control for a selected-value chip.
pub fn combobox_chip_remove<T: Clone + Eq + 'static>(cx: &App) -> ComboboxChipRemove<T> {
    let theme = UiTheme::read(cx).clone();
    ComboboxChipRemove::new()
        .style_with_state(move |state, base| {
            base.flex()
                .size(px(16.))
                .items_center()
                .justify_center()
                .rounded(px(3.))
                .text_color(theme.colors.muted_foreground)
                .when(!state.disabled, |base| {
                    base.hover(move |style| style.bg(theme.colors.background))
                })
        })
        .child(
            lucide(LucideIcon::X)
                .size(px(12.))
                .text_color(theme.colors.muted_foreground),
        )
}

/// Creates the styled text value shown by non-chip comboboxes.
pub fn combobox_value<T: Clone + Eq + 'static>() -> ComboboxValue<T> {
    ComboboxValue::new().style_with_state(move |_state, base| base.flex_1())
}

fn popup_style(base: Div, theme: &UiTheme) -> Div {
    base.min_w(px(144.))
        .max_h(px(288.))
        .overflow_hidden()
        .rounded(theme.radius.base)
        .bg(theme.colors.popover)
        .text_color(theme.colors.popover_foreground)
        .font_family(theme.fonts.body.clone())
        .text_size(px(14.))
        .border_1()
        .border_color(theme.colors.foreground.alpha(0.10))
        .shadow(vec![
            BoxShadow::new(px(0.), px(4.), theme.colors.foreground.alpha(0.12).into())
                .blur_radius(px(12.)),
        ])
}

//! The Base UI Autocomplete visual port using the shadcn Nova Combobox skin.
//!
//! Base GPUI implements Autocomplete by reusing its Combobox parts. shadcn/ui
//! 4.19.0 only ships the Nova wrapper for Combobox, so this file applies that
//! same editable-list treatment without changing Base GPUI autocomplete mode
//! or selection behavior.

pub use base_gpui::autocomplete::{
    AutocompleteArrow, AutocompleteBackdrop, AutocompleteClear, AutocompleteCollection,
    AutocompleteEmpty, AutocompleteGroup, AutocompleteGroupLabel, AutocompleteIcon,
    AutocompleteInput, AutocompleteInputGroup, AutocompleteItem, AutocompleteList,
    AutocompleteMode, AutocompletePopup, AutocompletePortal, AutocompletePositioner,
    AutocompleteRoot, AutocompleteSeparator, AutocompleteStatus, AutocompleteTrigger,
    AutocompleteValue,
};
use gpui::{App, ElementId, Styled, px};

use super::combobox;

/// Creates an autocomplete root with a caller-owned stable ID.
pub fn autocomplete_root<T: Clone + Eq + 'static>(id: impl Into<ElementId>) -> AutocompleteRoot<T> {
    AutocompleteRoot::new().id(id)
}

/// Creates the styled editable autocomplete input.
pub fn autocomplete_input<T: Clone + Eq + 'static>(
    id: impl Into<ElementId>,
    cx: &App,
) -> AutocompleteInput<T> {
    combobox::combobox_input(id, cx)
}

/// Creates the styled input group for custom autocomplete layouts.
pub fn autocomplete_input_group<T: Clone + Eq + 'static>(cx: &App) -> AutocompleteInputGroup<T> {
    combobox::combobox_input_group(cx)
}

/// Creates the styled autocomplete trigger.
pub fn autocomplete_trigger<T: Clone + Eq + 'static>(
    id: impl Into<ElementId>,
    cx: &App,
) -> AutocompleteTrigger<T> {
    combobox::combobox_trigger(id, cx)
}

/// Creates the styled autocomplete clear control.
pub fn autocomplete_clear<T: Clone + Eq + 'static>(
    id: impl Into<ElementId>,
    cx: &App,
) -> AutocompleteClear<T> {
    combobox::combobox_clear(id, cx)
